# Build 3x3 panel maps for each panel from segmentation nodes
seg = current_frame.segmentation
nodes = seg['nodes']

def cell_color(r0, c0):
    # find node whose bbox contains this top-left of a 6x6 block
    for n in nodes:
        b = n['boundary']
        rs = [p[0] for p in b]; cs = [p[1] for p in b]
        r1, c1 = min(rs), min(cs)
        if r1 == r0 and c1 == c0:
            return n['color'], n['pixels']
    return None, None

panels = {'A': (2,4), 'B': (2,38), 'C': (36,4), 'D': (36,36)}
for name,(pr,pc) in panels.items():
    print('panel', name)
    for i in range(3):
        row = []
        for j in range(3):
            c,p = cell_color(pr+8*i, pc+8*j)
            row.append(f'{c}{p if p!=36 else ""}')
        print('  ', row)
